#[cfg(test)]
mod tests {
    use std::{fs, path::Path};

    use super::*;

    #[test]
    fn heightmap_types_match_vanilla_explicit_ids_and_usage() {
        assert_eq!(VANILLA_HEIGHTMAP_TYPES.len(), 6);
        for (id, entry) in VANILLA_HEIGHTMAP_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
        }
        assert_eq!(VANILLA_HEIGHTMAP_WORLD_SURFACE_ID, 1);
        assert_eq!(VANILLA_HEIGHTMAP_MOTION_BLOCKING_ID, 4);
        assert_eq!(
            vanilla_heightmap_type(3).unwrap().usage,
            HeightmapUsage::LiveWorld
        );
        assert_eq!(
            vanilla_heightmap_type(5).unwrap().serialization_key,
            "MOTION_BLOCKING_NO_LEAVES"
        );
        assert_eq!(
            vanilla_heightmap_type(0).unwrap().debug_color_rgba,
            [255, 255, 0, 255]
        );
        assert_eq!(
            vanilla_heightmap_type(1).unwrap().debug_color_rgba,
            [0, 178, 0, 255]
        );
        assert_eq!(
            vanilla_heightmap_type(5).unwrap().debug_color_rgba,
            [0, 127, 127, 255]
        );
    }

    #[test]
    fn production_sources_do_not_handwrite_heightmap_catalog_facts() {
        let native = include_str!("../../bbb-native/src/runtime.rs");
        let projection = native
            .split("fn debug_heightmap_boxes(")
            .nth(1)
            .and_then(|source| {
                source
                    .split("#[derive(Debug, Clone, Copy, PartialEq)]")
                    .next()
            })
            .expect("native heightmap debug projection");
        assert_eq!(
            projection
                .matches("vanilla_heightmap_type(kind_id)")
                .count(),
            1
        );
        assert_eq!(projection.matches("debug_color_rgba").count(), 1);
        let native_tests = include_str!("../../bbb-native/src/runtime/tests.rs");
        let fixture = native_tests
            .split("fn debug_heightmap_boxes_follow_custom_entry_and_generated_descriptor_order")
            .nth(1)
            .and_then(|source| source.split("\n#[test]").next())
            .expect("native heightmap debug fixture");
        assert!(fixture.contains("VANILLA_HEIGHTMAP_TYPES"));
        assert!(fixture.contains("entry.debug_color_rgba"));
        assert!(
            !fixture.contains("color: ["),
            "native heightmap fixture restored hand-authored debug colors"
        );
        fn starts_with_integer_literal(source: &str) -> bool {
            source
                .strip_prefix('-')
                .unwrap_or(source)
                .chars()
                .next()
                .is_some_and(|character| character.is_ascii_digit())
        }
        fn contains_numeric_heightmap_kind_reference(source: &str) -> bool {
            let compact: String = source
                .chars()
                .filter(|character| !character.is_whitespace())
                .collect();
            let markers = [
                "kind_id:",
                ".kind_id,",
                ".kind_id==",
                ".kind_id!=",
                "sample_heightmap_first_available(",
                ".first_available(",
                "heightmap_data(",
                "kind_id==",
                "constVANILLA_HEIGHTMAP_KIND_COUNT:usize=",
            ];
            let old_kind_sets = [
                "vec![1,3,4,5]",
                "vec![0,1,2,3,4,5]",
                "vec![0,1,3,4,5]",
                "forkind_idin[1,3,4,5]",
                "packet.chunk_data.heightmaps=(0..=5)",
                "forkind_idin0..=5",
            ];
            markers.iter().any(|marker| {
                compact.match_indices(marker).any(|(offset, _)| {
                    starts_with_integer_literal(&compact[offset + marker.len()..])
                })
            }) || compact.contains("matches!(kind_id,")
                || old_kind_sets
                    .iter()
                    .any(|pattern| compact.contains(pattern))
        }
        assert!(contains_numeric_heightmap_kind_reference("kind_id: 1,"));
        assert!(contains_numeric_heightmap_kind_reference(
            "assert_eq!(map.kind_id, 4);"
        ));
        assert!(contains_numeric_heightmap_kind_reference(
            "sampler.first_available(0, 2, 3)"
        ));
        assert!(contains_numeric_heightmap_kind_reference(
            "matches!(kind_id, 1 | 3 | 4 | 5)"
        ));
        assert!(contains_numeric_heightmap_kind_reference(
            "vec![0, 1, 2, 3, 4, 5]"
        ));
        assert!(contains_numeric_heightmap_kind_reference(
            "for kind_id in 0..=5"
        ));
        assert!(!contains_numeric_heightmap_kind_reference(
            "kind_id: VANILLA_HEIGHTMAP_WORLD_SURFACE_ID,"
        ));
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/heightmap_types.rs") {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let semantic_consumer = [
                    "/bbb-native/src/",
                    "/bbb-world/src/",
                    "/bbb-net/src/",
                    "/bbb-control/src/",
                ]
                .iter()
                .any(|directory| display.contains(directory));
                if semantic_consumer && contains_numeric_heightmap_kind_reference(&source) {
                    violations.push(format!("{display}: numeric heightmap kind reference"));
                }
                if display.ends_with("/tests.rs") || display.contains("/tests/") {
                    continue;
                }
                if source.contains("DEBUG_HEIGHTMAP_COLORS") {
                    violations.push(format!("{display}: handwritten debug colors"));
                }
                for (offset, _) in source.match_indices(": i32 =") {
                    let start = source[..offset].rfind('\n').map_or(0, |index| index + 1);
                    let declaration = &source[start..offset];
                    let value = source[offset + ": i32 =".len()..].trim_start();
                    if declaration.contains("VANILLA_HEIGHTMAP_")
                        && value.as_bytes().first().is_some_and(u8::is_ascii_digit)
                    {
                        violations.push(display.to_string());
                    }
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "handwritten heightmap catalog facts: {violations:?}"
        );
    }
}
